<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';require_admin();
$me=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$id=(int)($_POST['user_id']??0);$action=$_POST['action']??'';
 if($id===(int)$me['id']){set_flash('error','Akun yang sedang digunakan tidak dapat diubah.');redirect('users');}
 if($action==='role'){$role=($_POST['role']??'user')==='admin'?'admin':'user';$pdo->prepare('UPDATE users SET role=? WHERE id=?')->execute([$role,$id]);set_flash('success','Hak akses berhasil diperbarui.');}
 elseif($action==='status'){$status=($_POST['status']??'active')==='suspended'?'suspended':'active';$pdo->prepare('UPDATE users SET status=? WHERE id=?')->execute([$status,$id]);set_flash('success','Status akun berhasil diperbarui.');}
 elseif($action==='verify'){$pdo->prepare('UPDATE users SET is_verified=1-is_verified WHERE id=?')->execute([$id]);set_flash('success','Status verifikasi diperbarui.');}
 elseif($action==='delete'){$pdo->prepare('DELETE FROM users WHERE id=?')->execute([$id]);set_flash('success','Akun berhasil dihapus.');}
 redirect('users');
}
$users=$pdo->query('SELECT u.*,COUNT(DISTINCT t.id) template_count,COUNT(DISTINCT f.follower_id) follower_count FROM users u LEFT JOIN twibbons t ON t.owner_id=u.id LEFT JOIN follows f ON f.creator_id=u.id GROUP BY u.id ORDER BY u.created_at DESC')->fetchAll();$flash=get_flash();
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kelola Pengguna — Semarakin</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="teal.css"><link rel="stylesheet" href="auth.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="./"><span class="brand-mark">S</span>Semarakin</a></div></header><main class="container"><div class="page-head dashboard-head"><div><span class="eyebrow">Administrator</span><h1 class="page-title" style="margin-top:12px">Kelola pengguna</h1><p class="subtitle">Atur akses, verifikasi kreator, dan jaga keamanan komunitas.</p></div><span class="btn btn-secondary"><?=count($users)?> akun</span></div><?php if($flash):?><div class="alert alert-<?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif?><section class="panel"><div class="table-scroll"><table><thead><tr><th>Pengguna</th><th>Status</th><th>Statistik</th><th>Bergabung</th><th>Aksi</th></tr></thead><tbody><?php foreach($users as $item):?><tr><td><strong><?=e($item['name'])?> <?=$item['is_verified']?'✓':''?></strong><small>@<?=e($item['username'])?> · <?=e($item['email'])?></small></td><td><span class="visibility <?=$item['role']==='admin'?'visibility-public':'visibility-unlisted'?>"><?=e($item['role'])?></span> <span class="visibility <?=$item['status']==='active'?'visibility-public':'visibility-private'?>"><?=e($item['status'])?></span></td><td><?=(int)$item['template_count']?> karya · <?=(int)$item['follower_count']?> pengikut</td><td><?=date('d M Y',strtotime($item['created_at']))?></td><td><?php if((int)$item['id']!==(int)$me['id']):?><div class="admin-actions"><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="verify"><input type="hidden" name="user_id" value="<?=(int)$item['id']?>"><button class="btn btn-secondary btn-sm"><?=$item['is_verified']?'Batalkan verifikasi':'Verifikasi'?></button></form><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="role"><input type="hidden" name="user_id" value="<?=(int)$item['id']?>"><input type="hidden" name="role" value="<?=$item['role']==='admin'?'user':'admin'?>"><button class="btn btn-secondary btn-sm"><?=$item['role']==='admin'?'Jadikan user':'Jadikan admin'?></button></form><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="user_id" value="<?=(int)$item['id']?>"><input type="hidden" name="status" value="<?=$item['status']==='active'?'suspended':'active'?>"><button class="btn btn-secondary btn-sm"><?=$item['status']==='active'?'Nonaktifkan':'Aktifkan'?></button></form><form method="post" data-confirm="Hapus akun beserta aksesnya secara permanen?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="user_id" value="<?=(int)$item['id']?>"><button class="btn btn-danger btn-sm">Hapus</button></form></div><?php else:?><small>Akun Anda</small><?php endif?></td></tr><?php endforeach?></tbody></table></div></section></main><footer class="footer">Semarakin · Produk digital dari Apins Digital</footer></body></html>
